CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
    new.updated_at = now();
    if to_jsonb(new) ? 'row_version' then
        new := jsonb_populate_record(
            new,
            jsonb_build_object(
                'row_version',
                coalesce((to_jsonb(old)->>'row_version')::integer, 0) + 1
            )
        );
    end if;
    return new;
end
$function$
